/* @lc app=leetcode id=3310 lang=kotlin */ class Solution { fun remainingMethods(n: Int, k: Int, invocations: Array<IntArray>): List<Int> = invocations.groupBy({ it[0] }, { it[1] }).let { g -> HashSet<Int>().also { it.add(k) }.let { seen -> generateSequence(listOf(k)) { f -> f.flatMap { g[it].orEmpty() }.filter { seen.add(it) }.takeIf { it.isNotEmpty() } }.count().let { if (invocations.any { it[0] !in seen && it[1] in seen }) (0 until n).toList() else (0 until n).filter { it !in seen } } } } }